     1	export const DEFAULT_LIMIT = 20;
     2	export const MAX_LIMIT = 100;
     3	
     4	export interface Page<T> {
     5	  data: T[];
     6	  pagination: { total: number; limit: number; offset: number };
     7	}
     8	
     9	export function normalizeLimit(limit?: number): number {
    10	  if (limit === undefined || Number.isNaN(limit)) return DEFAULT_LIMIT;
    11	  if (limit < 1) return DEFAULT_LIMIT;
    12	  return Math.min(limit, MAX_LIMIT);
    13	}
    14	
