import type { Booking } from '@prisma/client';
import { AppError, bookingConflict, notFound, validationFailed } from '../../shared/errors.js';
import {
  normalizeLimit,
  normalizeOffset,
  paginated,
  type Page,
} from '../../shared/pagination.js';
import { MINUTE_IN_MS, durationMinutes, isBefore, parseInstant } from '../../shared/time.js';
import * as repository from './repository.js';
import {
  BOOKING_ACTIVE,
  BOOKING_CANCELLED,
  MAX_DURATION_MINUTES,
  MIN_DURATION_MINUTES,
} from './schema.js';
import type {
  AvailabilityInput,
  CreateBookingInput,
  ListBookingsInput,
  UpdateBookingInput,
} from './schema.js';

const MINUTES_IN_DAY = 1440;
const MAX_WINDOW_MINUTES = 31 * MINUTES_IN_DAY;
const SUGGESTION_WINDOW_MINUTES = 7 * MINUTES_IN_DAY;

export interface Slot {
  startsAt: Date;
  endsAt: Date;
}

export interface Availability {
  roomId: string;
  from: Date;
  to: Date;
  slots: Slot[];
}

function earliest(a: Date, b: Date): Date {
  return isBefore(a, b) ? a : b;
}

function latest(a: Date, b: Date): Date {
  return isBefore(a, b) ? b : a;
}

function addMinutes(instant: Date, minutes: number): Date {
  return new Date(instant.getTime() + minutes * MINUTE_IN_MS);
}

function assertWindow(startsAt: Date, endsAt: Date): void {
  if (!isBefore(startsAt, endsAt)) {
    throw validationFailed('Booking must end after it starts');
  }
  if (isBefore(startsAt, new Date())) {
    throw validationFailed('Booking cannot start in the past', { startsAt });
  }
  const minutes = durationMinutes(startsAt, endsAt);
  if (minutes < MIN_DURATION_MINUTES || minutes > MAX_DURATION_MINUTES) {
    throw validationFailed('Booking duration is out of range', {
      durationMinutes: minutes,
      minDurationMinutes: MIN_DURATION_MINUTES,
      maxDurationMinutes: MAX_DURATION_MINUTES,
    });
  }
}

async function assertRoomExists(roomId: string): Promise<void> {
  const room = await repository.findRoomById(roomId);
  if (!room) {
    throw notFound('Room');
  }
}

async function assertUserExists(userId: string): Promise<void> {
  const user = await repository.findUserById(userId);
  if (!user) {
    throw notFound('User');
  }
}

// Sweeps the active bookings of a room in chronological order and returns the
// gaps left between them. The interval of a booking includes its start and
// excludes its end, so a gap may begin at the exact instant a booking ends.
function freeSlots(bookings: Booking[], from: Date, to: Date, minMinutes: number): Slot[] {
  const slots: Slot[] = [];
  let cursor = from;

  for (const booking of bookings) {
    if (isBefore(cursor, booking.startsAt)) {
      const slotEnd = earliest(booking.startsAt, to);
      if (durationMinutes(cursor, slotEnd) >= minMinutes) {
        slots.push({ startsAt: cursor, endsAt: slotEnd });
      }
    }
    cursor = latest(cursor, booking.endsAt);
    if (!isBefore(cursor, to)) {
      return slots;
    }
  }

  if (durationMinutes(cursor, to) >= minMinutes) {
    slots.push({ startsAt: cursor, endsAt: to });
  }
  return slots;
}

async function nextAvailableStart(
  roomId: string,
  startsAt: Date,
  endsAt: Date,
): Promise<Date | undefined> {
  const horizon = addMinutes(startsAt, SUGGESTION_WINDOW_MINUTES);
  const bookings = await repository.listActiveBetween(roomId, startsAt, horizon);
  const [slot] = freeSlots(bookings, startsAt, horizon, durationMinutes(startsAt, endsAt));
  return slot?.startsAt;
}

async function conflictFor(
  conflict: Booking,
  roomId: string,
  startsAt: Date,
  endsAt: Date,
): Promise<AppError> {
  const suggestion = await nextAvailableStart(roomId, startsAt, endsAt);
  return bookingConflict(conflict.id, suggestion ? { nextAvailableStart: suggestion } : {});
}

export async function createBooking(input: CreateBookingInput): Promise<Booking> {
  const startsAt = parseInstant(input.startsAt);
  const endsAt = parseInstant(input.endsAt);
  assertWindow(startsAt, endsAt);
  await assertRoomExists(input.roomId);
  await assertUserExists(input.userId);

  const conflict = await repository.findOverlapping(input.roomId, startsAt, endsAt);
  if (conflict) {
    throw await conflictFor(conflict, input.roomId, startsAt, endsAt);
  }

  return repository.create({
    roomId: input.roomId,
    userId: input.userId,
    title: input.title,
    startsAt,
    endsAt,
  });
}

export async function getBooking(id: string): Promise<Booking> {
  const booking = await repository.findById(id);
  if (!booking) {
    throw notFound('Booking');
  }
  return booking;
}

export async function listBookings(query: ListBookingsInput): Promise<Page<Booking>> {
  const limit = normalizeLimit(query.limit);
  const offset = normalizeOffset(query.offset);
  const [data, total] = await repository.list({
    roomId: query.roomId,
    userId: query.userId,
    status: query.status,
    from: query.from ? parseInstant(query.from) : undefined,
    to: query.to ? parseInstant(query.to) : undefined,
    limit,
    offset,
  });
  return paginated(data, total, limit, offset);
}

export async function listAvailability(query: AvailabilityInput): Promise<Availability> {
  const requestedFrom = parseInstant(query.from);
  const to = parseInstant(query.to);
  if (!isBefore(requestedFrom, to)) {
    throw validationFailed('Availability window must end after it starts');
  }
  if (durationMinutes(requestedFrom, to) > MAX_WINDOW_MINUTES) {
    throw validationFailed('Availability window is too long', {
      maxWindowMinutes: MAX_WINDOW_MINUTES,
    });
  }
  await assertRoomExists(query.roomId);

  // A booking can never start in the past, so a window that reaches back is
  // searched from now on.
  const from = earliest(latest(requestedFrom, new Date()), to);
  const minMinutes = query.durationMinutes ?? MIN_DURATION_MINUTES;
  const bookings = await repository.listActiveBetween(query.roomId, from, to);

  return { roomId: query.roomId, from, to, slots: freeSlots(bookings, from, to, minMinutes) };
}

export async function updateBooking(id: string, input: UpdateBookingInput): Promise<Booking> {
  const booking = await getBooking(id);
  const roomId = input.roomId ?? booking.roomId;
  const startsAt = input.startsAt !== undefined ? parseInstant(input.startsAt) : booking.startsAt;
  const endsAt = input.endsAt !== undefined ? parseInstant(input.endsAt) : booking.endsAt;
  const reschedules =
    input.roomId !== undefined || input.startsAt !== undefined || input.endsAt !== undefined;

  if (input.userId !== undefined) {
    await assertUserExists(input.userId);
  }

  if (reschedules) {
    assertWindow(startsAt, endsAt);
    if (input.roomId !== undefined) {
      await assertRoomExists(roomId);
    }
    // Only an active booking occupies its interval, so only an active booking
    // can be moved into a conflict.
    if (booking.status === BOOKING_ACTIVE) {
      const conflict = await repository.findOverlapping(roomId, startsAt, endsAt, id);
      if (conflict) {
        throw await conflictFor(conflict, roomId, startsAt, endsAt);
      }
    }
  }

  return repository.update(id, {
    ...(input.roomId !== undefined ? { roomId: input.roomId } : {}),
    ...(input.userId !== undefined ? { userId: input.userId } : {}),
    ...(input.title !== undefined ? { title: input.title } : {}),
    ...(input.startsAt !== undefined ? { startsAt } : {}),
    ...(input.endsAt !== undefined ? { endsAt } : {}),
  });
}

export async function cancelBooking(id: string): Promise<Booking> {
  const booking = await getBooking(id);
  if (booking.status === BOOKING_CANCELLED) {
    return booking;
  }
  return repository.updateStatus(id, BOOKING_CANCELLED);
}

export async function deleteBooking(id: string): Promise<void> {
  await getBooking(id);
  await repository.remove(id);
}
